"use client";

import * as React from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import { PencilEdit01Icon } from "@hugeicons/core-free-icons";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { CreditCardForm } from "@/components/ui/credit-card-form";
import { CreditCardValues, PaymentMethod } from "@/types/payment";
import { detectCardType } from "@/hooks/use-card-type";

interface EditPaymentDialogProps {
  method: PaymentMethod;
  onUpdate: (method: PaymentMethod) => void;
}

export function EditPaymentDialog({ method, onUpdate }: EditPaymentDialogProps) {
  const [open, setOpen] = React.useState(false);

  // Convert PaymentMethod to CreditCardValues
  // Note: We only have last4, but we can pre-fill it for UI consistency
  const [card, setCard] = React.useState<CreditCardValues>({
    cardholderName: "USER NAME", // Placeholder as we don't store it in PaymentMethod
    cardNumber: `•••• •••• •••• ${method.last4 || ""}`,
    expiryMonth: method.expiryMonth?.toString().padStart(2, "0") || "",
    expiryYear: method.expiryYear?.toString().slice(-2) || "",
    cvv: "",
  });

  const isValid =
    card.cardholderName.trim() &&
    (card.cardNumber.includes("•") || card.cardNumber.replace(/\s/g, "").length >= 15) &&
    card.expiryMonth &&
    parseInt(card.expiryMonth) <= 12 &&
    card.expiryYear;

  const handleSave = () => {
    if (!isValid) return;

    // In a real app, only changed fields would be sent
    const type = detectCardType(card.cardNumber.includes("•") ? method.type : card.cardNumber);
    const cleaned = card.cardNumber.replace(/\s/g, "");

    const updatedMethod: PaymentMethod = {
      ...method,
      type: (type === "unknown" || type === "discover" ? method.type : type) as PaymentMethod["type"],
      last4: cleaned.includes("•") ? method.last4 : cleaned.slice(-4),
      expiryMonth: parseInt(card.expiryMonth),
      expiryYear: parseInt(card.expiryYear.length === 2 ? `20${card.expiryYear}` : card.expiryYear),
    };

    onUpdate(updatedMethod);
    setOpen(false);
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="ghost" size="icon" className="size-8">
          <HugeiconsIcon icon={PencilEdit01Icon} className="size-4" />
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-lg border-border/50 bg-muted/20 backdrop-blur-xl">
        <DialogHeader>
          <DialogTitle>Edit Payment Method</DialogTitle>
          <DialogDescription>
            Update your card information for this payment method.
          </DialogDescription>
        </DialogHeader>
        <CreditCardForm 
          value={card} 
          onChange={setCard} 
          cardType={method.type}
        />
        <DialogFooter>
          <Button variant="outline" onClick={() => setOpen(false)}>
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={!isValid}>
            Save Changes
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
